def parse_thong_so(raw_str):
    if not raw_str:
        return json.dumps({}, ensure_ascii=False)
    res = {}
    for part in raw_str.split(';'):
        if ':' in part:
            k, v = part.split(':', 1)
            res[k.strip()] = v.strip()
    return json.dumps(res, ensure_ascii=False)

def parse_the(raw_str):
    if not raw_str:
        return json.dumps([], ensure_ascii=False)
    tags = [t.strip() for t in raw_str.split(',') if t.strip()]
    return json.dumps(tags, ensure_ascii=False)

def main():
    sys.stdout.reconfigure(encoding='utf-8')
    conn = mysql.connector.connect(
        host='localhost',
        user='root',
        password='1234',
        database='he_thong_ban_hang_ai'
    )
    cursor = conn.cursor()

    sql = """
    INSERT INTO san_pham (
        ma_danh_muc, ten, duong_dan, ma_sku, thuong_hieu, mo_ta_ngan, mo_ta,
        thong_so, the, gia_goc, gia_ban, so_luong_ton, duong_dan_anh_dai_dien,
        diem_danh_gia_trung_binh, tong_danh_gia, tong_da_ban, dang_hoat_dong,
        noi_bat, ngay_tao, ngay_cap_nhat, phan_tram_giam
    ) VALUES (
        %s, %s, %s, %s, %s, %s, %s,
        %s, %s, %s, %s, %s, %s,
        %s, %s, %s, %s,
        %s, %s, %s, %s
    )
    ON DUPLICATE KEY UPDATE
        ten = VALUES(ten),
        gia_goc = VALUES(gia_goc),
        gia_ban = VALUES(gia_ban),
        so_luong_ton = VALUES(so_luong_ton),
        thuong_hieu = VALUES(thuong_hieu),
        mo_ta_ngan = VALUES(mo_ta_ngan),
        mo_ta = VALUES(mo_ta),
        thong_so = VALUES(thong_so),
        the = VALUES(the),
        ngay_cap_nhat = NOW()
    """

    inserted = 0
    updated = 0
    brand_color_map = {
        'Apple': '1a1a2e',
        'Samsung': '14213d',
        'Baseus': '003049',
        'Spigen': '2b2d42',
        'UAG': '22223b',
        'ESR': '3d348b',
        'Incase': '283618'
    }

    for row in RAW_ROWS:
        (
            ma_danh_muc, ten, duong_dan, ma_sku, thuong_hieu, mo_ta_ngan, mo_ta,
            thong_so_raw, the_raw, gia_goc, gia_ban, so_luong_ton, img,
            diem_dg, tong_dg, tong_ban, hoat_dong, noi_bat, ngay_tao, ngay_cap_nhat, phan_tram_giam
        ) = row

        thong_so_json = parse_thong_so(thong_so_raw)
        the_json = parse_the(the_raw)

        # Tạo ảnh placeholder đẹp nếu chưa có ảnh
        if not img:
            color = brand_color_map.get(thuong_hieu, '1f2937')
            encoded_text = urllib.parse.quote(f"{thuong_hieu} {ten[:20]}")
            img_url = f"https://placehold.co/500x500/{color}/ffffff?text={encoded_text}"
        else:
            img_url = img

        cursor.execute(sql, (
            ma_danh_muc, ten, duong_dan, ma_sku, thuong_hieu, mo_ta_ngan, mo_ta,
            thong_so_json, the_json, gia_goc, gia_ban, so_luong_ton, img_url,
            diem_dg, tong_dg, tong_ban, hoat_dong, noi_bat, ngay_tao, ngay_cap_nhat, phan_tram_giam
        ))
        if cursor.rowcount == 1:
            inserted += 1
        elif cursor.rowcount == 2:
            updated += 1

    conn.commit()
    print(f"✅ Hoàn tất nhập dữ liệu sản phẩm!")
    print(f" - Đã thêm mới: {inserted} sản phẩm")
    print(f" - Đã cập nhật: {updated} sản phẩm")
    print(f" - Tổng bản ghi xử lý: {len(RAW_ROWS)} sản phẩm (từ SP00892 đến SP01000)")

    # Kiểm tra tổng số lượng trong san_pham
    cursor.execute("SELECT COUNT(*) FROM san_pham")
    total = cursor.fetchone()[0]
    print(f" - Tổng số sản phẩm hiện tại trong bảng san_pham: {total}")

    conn.close()

if __name__ == '__main__':
    main()
